#include <string>
#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minCharacters(string a, string b) {
        int m = a.size(), n = b.size();
        vector<int> cnt_a(26, 0), cnt_b(26, 0);
        for (char c : a) cnt_a[c - 'a']++;
        for (char c : b) cnt_b[c - 'a']++;

        int max_a = *max_element(cnt_a.begin(), cnt_a.end());
        int max_b = *max_element(cnt_b.begin(), cnt_b.end());
        int ans = (m - max_a) + (n - max_b);

        int pref_a = 0, pref_b = 0;
        for (int i = 0; i < 25; ++i) {
            pref_a += cnt_a[i];
            pref_b += cnt_b[i];
            int cost1 = (m - pref_a) + pref_b;
            int cost2 = (n - pref_b) + pref_a;
            ans = min({ans, cost1, cost2});
        }
        return ans;
    }
};

class Solution {
    public int minCharacters(String a, String b) {
        int m = a.length(), n = b.length();
        int[] cntA = new int[26];
        int[] cntB = new int[26];
        for (int i = 0; i < m; ++i) cntA[a.charAt(i) - 'a']++;
        for (int i = 0; i < n; ++i) cntB[b.charAt(i) - 'a']++;

        int maxA = 0, maxB = 0;
        for (int i = 0; i < 26; ++i) {
            if (cntA[i] > maxA) maxA = cntA[i];
            if (cntB[i] > maxB) maxB = cntB[i];
        }
        int ans = (m - maxA) + (n - maxB);

        int prefA = 0, prefB = 0;
        for (int i = 0; i < 25; ++i) {
            prefA += cntA[i];
            prefB += cntB[i];
            int cost1 = (m - prefA) + prefB;
            int cost2 = (n - prefB) + prefA;
            ans = Math.min(ans, Math.min(cost1, cost2));
        }
        return ans;
    }
}

/**
 * @param {string} a
 * @param {string} b
 * @return {number}
 */
var minCharacters = function(a, b) {
    const m = a.length, n = b.length;
    const cntA = Array(26).fill(0);
    const cntB = Array(26).fill(0);
    for (let i = 0; i < m; ++i) cntA[a.charCodeAt(i) - 97]++;
    for (let i = 0; i < n; ++i) cntB[b.charCodeAt(i) - 97]++;

    let ans = (m - Math.max(...cntA)) + (n - Math.max(...cntB));
    let prefA = 0, prefB = 0;
    for (let i = 0; i < 25; ++i) {
        prefA += cntA[i];
        prefB += cntB[i];
        const cost1 = (m - prefA) + prefB;
        const cost2 = (n - prefB) + prefA;
        ans = Math.min(ans, cost1, cost2);
    }
    return ans;
};
